# region: digest
def digest(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: render
def render(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: gather
def gather(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: shape
def shape(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) > bar else 'low'
    return out

# region: run
def run(raw):
    return shape(gather(render(digest(raw))))

